impl<E> CustomerPublisher<E>
where
    E: OutboxEventMarker<CoreCustomerEvent>,
{
    pub fn new(outbox: &Outbox<E>) -> Self {
        Self {
            outbox: outbox.clone(),
        }
    }

    pub async fn publish_in_op(
        &self,
        db: &mut impl es_entity::AtomicOperation,
        entity: &Customer,
        new_events: es_entity::LastPersisted<'_, CustomerEvent>,
    ) -> Result<(), sqlx::Error> {
        use CustomerEvent::*;
        let publish_events = new_events
            .map(|event| match &event.event {
                Initialized { .. } => CoreCustomerEvent::CustomerCreated {
                    entity: PublicCustomer::from(entity),
                },
                Frozen { .. } => CoreCustomerEvent::CustomerFrozen {
                    entity: PublicCustomer::from(entity),
                },
                Unfrozen { .. } => CoreCustomerEvent::CustomerUnfrozen {
                    entity: PublicCustomer::from(entity),
                },
                Closed { .. } => CoreCustomerEvent::CustomerClosed {
                    entity: PublicCustomer::from(entity),
                },
            })
            .collect::<Vec<_>>();
        self.outbox
            .publish_all_persisted(db, publish_events)
            .await?;
        Ok(())
    }
}

